// Venom DS — WCAG contrast gate. Reads validation/theme-token-manifest.json
// (generated by build-tokens.js) and checks every meaningful fg/bg token
// pairing in every theme: AA blocking (4.5 text / 3.0 UI), AAA reported for
// venom-hc. Returns { failures, results } and throws on any AA failure.
async function checkVenomContrast(io) {
  const { readFile, log } = io;
  const manifest = JSON.parse(await readFile('validation/theme-token-manifest.json'));

  function srgb(c) { c /= 255; return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4); }
  function lum(hex) {
    const m = hex.trim().match(/^#([0-9a-f]{6})$/i);
    if (!m) return null; // rgba()/none — skipped (scrim, shadows)
    const n = parseInt(m[1], 16);
    return 0.2126 * srgb((n >> 16) & 255) + 0.7152 * srgb((n >> 8) & 255) + 0.0722 * srgb(n & 255);
  }
  function ratio(fg, bg) {
    const a = lum(fg), b = lum(bg);
    if (a == null || b == null) return null;
    const [hi, lo] = a > b ? [a, b] : [b, a];
    return (hi + 0.05) / (lo + 0.05);
  }

  const SURFACES = ['surface.canvas', 'surface.primary', 'surface.secondary', 'surface.raised'];
  const STATUS = ['healthy', 'degraded', 'warning', 'critical', 'info', 'unknown', 'inactive'];
  const TIERS = ['lite', 'pro', 'max'];

  const results = [];
  const failures = [];
  for (const [theme, t] of Object.entries(manifest.themes)) {
    const min = (fg, bg, need, label) => {
      const r = ratio(t[fg], t[bg]);
      if (r == null) return;
      const pass = r >= need;
      results.push({ theme, pair: fg + ' on ' + bg, ratio: +r.toFixed(2), need, pass, label });
      if (!pass) failures.push(theme + ': ' + fg + ' on ' + bg + ' = ' + r.toFixed(2) + ' < ' + need);
    };
    for (const s of SURFACES) {
      min('text.primary', s, 4.5); min('text.secondary', s, 4.5); min('text.muted', s, 4.5);
    }
    min('text.link', 'surface.canvas', 4.5); min('text.link', 'surface.primary', 4.5);
    min('text.on-accent', 'accent.default', 4.5);
    min('accent.text', 'surface.canvas', 4.5); min('accent.text', 'surface.primary', 4.5);
    for (const st of STATUS) {
      min('status.' + st + '.fg', 'status.' + st + '.bg', 4.5);
      min('status.' + st + '.fg', 'surface.primary', 3.0, 'icon/graphic on surface');
    }
    for (const ti of TIERS) min('tier.' + ti + '.fg', 'tier.' + ti + '.bg', 4.5);
    min('action.primary.fg', 'action.primary.bg', 4.5);
    min('action.secondary.fg', 'action.secondary.bg', 4.5);
    min('action.destructive.fg', 'action.destructive.bg', 4.5);
    min('border.strong', 'surface.primary', 3.0, 'control boundary');
    min('focus.ring', 'surface.canvas', 3.0, 'focus ring');
    if (theme === 'venom-hc') {
      // AAA target where feasible — reported, blocking for core text only.
      min('text.primary', 'surface.canvas', 7.0, 'AAA');
      min('text.secondary', 'surface.canvas', 7.0, 'AAA');
    }
  }
  const summary = { checked: results.length, failed: failures.length, failures };
  log('CONTRAST: ' + results.length + ' pairings checked, ' + failures.length + ' failures');
  if (failures.length) throw new Error('CONTRAST FAILURES:\n' + failures.join('\n'));
  return { summary, results };
}
if (typeof module !== 'undefined') module.exports = { checkVenomContrast };
